import{A as c}from"../assets/api.js";chrome.runtime.onInstalled.addListener(()=>{console.log("[Job Authenticity Agent] Service Worker Installed.")});chrome.runtime.onMessage.addListener((e,i,r)=>(console.log("[Job Authenticity Agent] Worker received message type:",e.type),e.type==="SCORE_PAGE"?(c.scorePage(e.url,e.rawText,e.titleHint,e.companyHint).then(t=>r({success:!0,data:t})).catch(t=>r({success:!1,error:t.message})),!0):e.type==="SAVE_JOB"?(c.saveJob(e.job,e.scored,e.notes).then(t=>r({success:!0,data:t})).catch(t=>r({success:!1,error:t.message})),!0):e.type==="GET_SAVED_JOBS"?(c.getSavedJobs().then(t=>r({success:!0,data:t})).catch(t=>r({success:!1,error:t.message})),!0):e.type==="DELETE_SAVED_JOB"?(c.deleteSavedJob(e.id).then(()=>r({success:!0})).catch(t=>r({success:!1,error:t.message})),!0):!1));chrome.action.onClicked.addListener(e=>{e.id&&chrome.tabs.sendMessage(e.id,{type:"TOGGLE_SIDEBAR"}).catch(i=>{console.log("[Job Authenticity Agent] Direct message skipped (tab is not a supported webpage or needs refresh):",i.message)})});
